public float GetBlockAdjustedDamage(float dmg, int stat)
{
	float num = 1f;
	if (c.playerIdx > -1)
	{
		Player player = c.GetPlayer();
		if (c.equipment.active)
		{
			if (c.equipment.HasSwordShieldLoadout())
			{
				if (c.equipment.twoHanded[c.equipment.loadoutIdx] || c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx < 0)
				{
					num = 0.5f;
				}
				else if (c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx > -1 && c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx < 128)
				{
					InvLoot invLoot = player.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, 1].invIdx];
					if (LootCatalog.category[1].loot[invLoot.catalogIdx].type == 4)
					{
						num = 0.5f;
					}
					else
					{
						float num2 = 0f;
						switch (stat)
						{
						case 0:
							num2 = GetDefense(0);
							num += invLoot.GetValue(2, player);
							break;
						case 2:
							num2 = GetDefense(0);
							num += invLoot.GetValue(3, player);
							break;
						case 3:
							num2 = GetDefense(0);
							num += invLoot.GetValue(4, player);
							break;
						case 6:
							num2 = GetDefense(0);
							num += invLoot.GetValue(5, player);
							break;
						case 5:
							num2 = GetDefense(0);
							num += invLoot.GetValue(6, player);
							break;
						case 8:
							num2 = GetDefense(0);
							num += invLoot.GetValue(7, player);
							break;
						case 9:
							num2 = GetDefense(0);
							num += invLoot.GetValue(8, player);
							break;
						}
						num /= 100f;
						if (GameModeMgr.IsGameEnhanced())
						{
							float num3 = ((num > 0f) ? 1f : (-1f));
							num *= num3;
							float num4 = num * 200f / (1f - num);
							num4 *= num3;
							num = (num4 + num2) / (num4 + num2 + 200f);
						}
						if (num > 1f)
						{
							num = 1f;
						}
						if (num < 0f)
						{
							num = 0f;
						}
					}
				}
			}
			else
			{
				num = 0.5f;
			}
		}
	}
	else
	{
		MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
		num = ((stat != 0) ? (monsterDef.blockMagReduce / 100f) : (monsterDef.blockDmgReduce / 100f));
	}
	return dmg * (1f - num);
}
public float GetShieldAdjustedPoise()
{
	float num = 1f;
	if (c.playerIdx > -1)
	{
		if (c.equipment.active)
