			{
				if (c.equipment.twoHanded[c.equipment.loadoutIdx] || c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx < 0)
				{
					num = 0.5f;
				}
				else if (c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx > -1 && c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx < 128)
				{
					Player player = c.GetPlayer();
					InvLoot invLoot = player.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, 1].invIdx];
					num = ((!GameModeMgr.IsGameEnhanced()) ? (invLoot.GetValue(0, player) / 100f) : (LootCatalog.category[1].loot[invLoot.catalogIdx].values[0] / 100f));
					if (PlayerMgr.GetMainPlayer().sanctuaryBonus[8])
					{
						num += (1f - num) * 0.1f;
					}
					if (num > 1f)
					{
						num = 1f;
					}
					if (num < 0f)
					{
						num = 0f;
					}
				}
			}
			else
			{
				num = 0.5f;
			}
		}
		if (GameModeMgr.IsGameEnhanced())
		{
			float maxPoise = c.stats.GetMaxPoise();
			float num2 = num * 40f / (1f - num);
			num = (num2 + maxPoise) / (num2 + maxPoise + 40f);
		}
		else
		{
			float maxPoise2 = c.stats.GetMaxPoise();
			float num3 = maxPoise2 / (maxPoise2 + 40f);
			num += (1f - num) * num3;
		}
	}
	else
	{
		num = MonsterCatalog.catalog[c.monsterIdx].blockReduce / 100f;
	}
	return 1f - num;
