public int selMaterial;
public int page;
public int returnLevel;
public const int UPGRADE_TRANSMUTE = 0;
public const int UPGRADE_UPGRADE = 1;
public int upgradeType;
public InvLoot compareLoot;
private float upgradeScroll;
public Upgrades()
{
	hijackDraw = true;
	hijackUpdate = true;
}
public void Init(Player p, int returnLevel, int upgradeType)
{
	List<string> list = new List<string>();
	List<int> list2 = new List<int>();
	for (int i = 0; i < p.playerInv.inventory.Length; i++)
	{
		InvLoot invLoot = p.playerInv.inventory[i];
		if (invLoot == null)
		{
			continue;
		}
		int category = invLoot.category;
		if ((uint)category > 2u)
		{
			continue;
		}
		if (upgradeType == 0)
		{
			LootDef lootDef = LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx];
			LootDef[] loot = LootCatalog.category[invLoot.category].loot;
			foreach (LootDef lootDef2 in loot)
			{
				if (lootDef2.upgradePath[0].reqLoot != null)
				{
					bool flag = true;
					if (invLoot.category == 2)
					{
						flag = (lootDef2.values[7] > 0f && lootDef.values[7] > 0f) || (lootDef2.values[7] <= 0f && lootDef.values[7] <= 0f);
					}
					int altType = GetAltType(lootDef2.category, lootDef2.type, out var altType2);
					if (lootDef.name == "spear_oar" || lootDef.name == "mace_pot")
					{
						flag = false;
					}
					if (((lootDef2.type == lootDef.type || altType == lootDef.type || altType2 == lootDef.type) & flag) && lootDef2.name != lootDef.name && p.playerInv.HasInvItem(lootDef2.upgradePath[0].reqLoot) && !list2.Contains(i))
					{
						list.Add(invLoot.name);
						list2.Add(i);
						break;
					}
				}
			}
		}
		else
		{
			if (invLoot.upgrade >= invLoot.GetUpgradeMax())
			{
				continue;
			}
			bool flag2 = true;
			switch (invLoot.category)
			{
			case 0:
				if (LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx].type == 15)
				{
					flag2 = false;
				}
				break;
			case 1:
				if (LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx].type == 4)
				{
					flag2 = false;
				}
				break;
			}
			if (flag2)
			{
				list.Add(invLoot.name);
				list2.Add(i);
			}
		}
	}
	srcLootInvStr = list.ToArray();
	srcLootInvIdx = list2.ToArray();
	categories = LootCatalog.GetCategories(srcLootInvStr);
	selCategory = 0;
	page = 0;
	this.returnLevel = returnLevel;
	this.upgradeType = upgradeType;
	SetLootFromCategory(p);
}
private int GetAltType(int category, int type, out int altType2)
{
	altType2 = type;
	int result = type;
	if (category == 0)
	{
		switch (type)
		{
		case 17:
			result = 6;
			break;
		case 6:
			result = 17;
			break;
		case 18:
			result = 20;
			altType2 = 1;
			break;
		case 20:
			result = 1;
			altType2 = 18;
			break;
		case 1:
			result = 20;
			altType2 = 18;
			break;
		case 19:
			result = 11;
			altType2 = 21;
			break;
		case 11:
			result = 21;
			altType2 = 19;
			break;
		case 21:
			result = 11;
			altType2 = 19;
			break;
		case 13:
			result = 4;
			break;
		case 4:
			result = 13;
			break;
		}
	}
	return result;
}
public void SetLootFromCategory(Player p)
{
	List<LootDef> lDefList = new List<LootDef>();
	List<InvLoot> invLootList = new List<InvLoot>();
	List<int> list = new List<int>();
	for (int i = 0; i < srcLootInvStr.Length; i++)
	{
		int num = categories[selCategory];
		for (int j = 0; j < LootCatalog.category[num].loot.Length; j++)
		{
			if (LootCatalog.category[num].loot[j].name == srcLootInvStr[i])
			{
				LootDef lootDef = new LootDef(LootCatalog.category[num].loot[j]);
				lootDef.titleStr = new StringBuilder(lootDef.title[Game1.language]);
				InvLoot invLoot = new InvLoot();
				invLoot.InitFromName(lootDef.name);
				invLoot.upgrade = p.playerInv.inventory[srcLootInvIdx[i]].upgrade;
				invLoot.equipped = p.playerInv.inventory[srcLootInvIdx[i]].equipped;
				lootDef.durability = LootCatalog.category[num].loot[j].durability;
				lDefList.Add(lootDef);
				invLootList.Add(invLoot);
				list.Add(srcLootInvIdx[i]);
			}
		}
	}
	lootInvIdx = InvPicker.SortItemListWithIdx(list, p, out var idxList).ToArray();
	this.lootDef = idxList.Select((int x) => lDefList[x]).ToArray();
	this.invLoot = idxList.Select((int x) => invLootList[x]).ToArray();
	itemAlpha = new float[this.lootDef.Length];
}
public override void SelectedUpdate(Player p)
{
	if (selItem >= this.lootDef.Length)
	{
		selItem = 0;
	}
	if (upgradeScroll < 0f)
	{
		upgradeScroll = 0f;
	}
	if (CharMgr.GetPlayerCharacter(p) == null)
	{
		return;
	}
	if (p.keyLeft)
	{
		Sound.PlaySelect();

	}
	public LootDef(LootDef otherDef)
	{
		SetCategory(otherDef.category);
		type = otherDef.type;
		upgrade = otherDef.upgrade;
		name = otherDef.name;
		title = new string[otherDef.title.Length];
		desc = new string[otherDef.desc.Length];
		for (int i = 0; i < title.Length; i++)
		{
			title[i] = otherDef.title[i];
		}
		for (int j = 0; j < desc.Length; j++)
		{
			desc[j] = otherDef.desc[j];
		}
		texture = otherDef.texture;
		flags = otherDef.flags;
		weight = otherDef.weight;
		special = otherDef.special;
		value = otherDef.value;
		for (int k = 0; k < values.Length; k++)
		{
			values[k] = otherDef.values[k];
		}
